create or replace function public.ridgewood_freeze_issued_document_revision() returns trigger language plpgsql set search_path = public as $$ begin if old.state in ('published','superseded','withdrawn') then if new.document_record_id is distinct from old.document_record_id or new.revision_number is distinct from old.revision_number or new.source_data is distinct from old.source_data or new.published_source_snapshot is distinct from old.published_source_snapshot or new.based_on_revision_id is distinct from old.based_on_revision_id or new.storage_provider is distinct from old.storage_provider or new.storage_locator is distinct from old.storage_locator or new.mime_type is distinct from old.mime_type or new.content_hash is distinct from old.content_hash or new.storage_bucket is distinct from old.storage_bucket or new.storage_object_key is distinct from old.storage_object_key or new.artifact_mime_type is distinct from old.artifact_mime_type or new.artifact_size_bytes is distinct from old.artifact_size_bytes or new.artifact_sha256 is distinct from old.artifact_sha256 or new.created_by is distinct from old.created_by or new.published_by is distinct from old.published_by or new.created_at is distinct from old.created_at or new.published_at is distinct from old.published_at then raise exception 'Issued document revision content, provenance, and artifact are immutable; create a new draft revision instead.'; end if; end if; return new; end; $$;
